/** @return array<string,mixed> */
function iprState(mysqli$db,string$p):array{$like=$db->real_escape_string($p.'%');$names=array_column($db->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME LIKE '$like' ORDER BY BINARY TABLE_NAME")->fetch_all(MYSQLI_ASSOC),'TABLE_NAME');$out=[];foreach($names as$n){$q=iprQ($n);$e=$db->real_escape_string($n);$rows=[];foreach($db->query("SELECT * FROM $q")->fetch_all(MYSQLI_ASSOC)as$row){$bytes=[];foreach($row as$column=>$value)$bytes[$column]=$value===null?null:base64_encode((string)$value);$rows[]=json_encode($bytes,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}sort($rows,SORT_STRING);$create=$db->query("SHOW CREATE TABLE $q")->fetch_assoc();$out[$n]=['table'=>$db->query("SELECT ENGINE,TABLE_COLLATION,AUTO_INCREMENT,CREATE_OPTIONS,TABLE_COMMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e'")->fetch_assoc(),'create'=>array_values($create),'columns'=>$db->query("SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,IS_GENERATED,GENERATION_EXPRESSION,CHARACTER_SET_NAME,COLLATION_NAME,COLUMN_COMMENT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e' ORDER BY ORDINAL_POSITION")->fetch_all(MYSQLI_ASSOC),'indexes'=>$db->query("SELECT INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART,COLLATION,INDEX_TYPE,IGNORED,INDEX_COMMENT FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e' ORDER BY BINARY INDEX_NAME,SEQ_IN_INDEX")->fetch_all(MYSQLI_ASSOC),'constraints'=>$db->query("SELECT CONSTRAINT_NAME,CONSTRAINT_TYPE FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='$e' ORDER BY BINARY CONSTRAINT_NAME")->fetch_all(MYSQLI_ASSOC),'row_count'=>count($rows),'row_bytes'=>$rows,'row_bytes_sha256'=>hash('sha256',implode("\n",$rows))];}return$out;}
