function iprStart(array$env):array{$port=iprPort();$pipes=[];$r=proc_open([PHP_BINARY,'-d','expose_php=0','-S','127.0.0.1:'.$port,dirname(__DIR__).'/Support/inspection_planning_runtime_router.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),$env);if(!is_resource($r))throw new TestFailure('SETUP_FAILURE: HTTP start');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$end=microtime(true)+5;do{$s=@stream_socket_client('tcp://127.0.0.1:'.$port,$e,$m,.1);if($s!==false){fclose($s);return compact('r','pipes','port');}usleep(20000);}while(microtime(true)<$end);throw new TestFailure('SETUP_FAILURE: HTTP listen');}
