function iprHttp(int$port,string$m,string$path,string$body=''):array{$s=stream_socket_client('tcp://127.0.0.1:'.$port,$e,$x,5);if($s===false)throw new TestFailure('SETUP_FAILURE: HTTP connect');fwrite($s,"$m $path HTTP/1.1\r\nHost: planning.example\r\nConnection: close\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: ".strlen($body)."\r\n\r\n$body");stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s))$raw.=(string)fread($s,65536);fclose($s);[$h,$b]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$ls=explode("\r\n",$h);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($ls),$match);$headers=[];foreach($ls as$l)if(str_contains($l,':')){[$k,$v]=explode(':',$l,2);$headers[strtolower(trim($k))][]=trim($v);}return['status'=>(int)($match[1]??0),'headers'=>$headers,'body'=>$b];}
function iprFailure(array$r,string$route):void{$body=match($route){'schedule'=>"Не удалось запланировать инспекцию. Повторите попытку.\n",'calendar'=>"Календарь временно недоступен. Обновите страницу или вернитесь к объектам монтажа.\n",'control'=>"Контроль объектов временно недоступен. Повторите попытку.\n",default=>null};assertSameValue(503,$r['status'],"$route 503");assertSameValue(false,isset($r['headers']['location']),"$route no redirect");if($route==='queue'){assertSameValue(['text/plain; charset=UTF-8'],$r['headers']['content-type']??[],'queue content type');assertSameValue(1,preg_match('/\AService unavailable\. Reference: [0-9a-f]{12}\n\z/D',$r['body']),'queue exact opaque body/no partial HTML');}else assertSameValue($body,$r['body'],"$route exact UTF-8 body/newline/no partial HTML");}
function iprRemove(string$p):void{if(!is_dir($p))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($p,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$f)$f->isDir()?@rmdir($f->getPathname()):@unlink($f->getPathname());@rmdir($p);}
